parameters.jsCode:
// WF02 validates one trusted internal invocation.
//
// Supported transports:
// - Internal Invocation Trigger: payload is in $json
// - Webhook Trigger: payload is in $json.body
//
// Supported invocation types:
// - WF01 initial request
// - WF03 correction request
// - WF98 operation retry
// - WF98 missing initial dispatch recovery
// - WF98 missing correction dispatch recovery

const items = $input.all();

if (items.length !== 1) {
  throw new Error(
    `WF02 expected exactly one input item, received ${items.length}`,
  );
}

function assertPlainObject(value, fieldName) {
  if (
    value === null ||
    typeof value !== 'object' ||
    Array.isArray(value)
  ) {
    throw new Error(
      `${fieldName} must be a JSON object`,
    );
  }
}

function hasOwn(object, fieldName) {
  return Object.prototype.hasOwnProperty.call(
    object,
    fieldName,
  );
}

function rejectUnknownFields(
  object,
  allowedFields,
) {
  const unknownFields = Object.keys(
    object,
  ).filter(
    (fieldName) =>
      !allowedFields.has(fieldName),
  );

  if (unknownFields.length > 0) {
    throw new Error(
      `Unknown top-level fields: ${unknownFields.join(', ')}`,
    );
  }
}

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function requiredUuid(
  value,
  fieldName,
) {
  if (typeof value !== 'string') {
    throw new Error(
      `${fieldName} must be a UUID string`,
    );
  }

  const normalized = value
    .trim()
    .toLowerCase();

  if (!UUID_PATTERN.test(normalized)) {
    throw new Error(
      `${fieldName} must contain a valid UUID`,
    );
  }

  return normalized;
}

function requiredText(
  value,
  fieldName,
  maxLength = 200,
) {
  if (typeof value !== 'string') {
    throw new Error(
      `${fieldName} must be a string`,
    );
  }

  const normalized = value.trim();

  if (!normalized) {
    throw new Error(
      `${fieldName} must not be blank`,
    );
  }

  if (normalized.length > maxLength) {
    throw new Error(
      `${fieldName} exceeds ${maxLength} characters`,
    );
  }

  return normalized;
}

const rawInput = items[0].json ?? {};

assertPlainObject(
  rawInput,
  'raw input',
);

const webhookTransport =
  hasOwn(rawInput, 'body');

let input = rawInput;

if (webhookTransport) {
  assertPlainObject(
    rawInput.body,
    'webhook body',
  );

  input = rawInput.body;
}

assertPlainObject(
  input,
  'input',
);

const caseId = requiredUuid(
  input.case_id,
  'case_id',
);

const correlationId = requiredUuid(
  input.correlation_id,
  'correlation_id',
);

const triggerSource = requiredText(
  input.trigger_source,
  'trigger_source',
  20,
);

function buildOutput({
  invocationKind,
  requestCycleKey = null,
  failedSubmissionId = null,
  externalOperationId = null,
  recoveryReason = null,
}) {
  return [
    {
      json: {
        workflow_name:
          'WF02 — Request Client Data',

        input_transport:
          webhookTransport
            ? 'webhook'
            : 'internal_invocation',

        invocation_kind:
          invocationKind,

        trigger_source:
          triggerSource,

        case_id:
          caseId,

        correlation_id:
          correlationId,

        request_cycle_key:
          requestCycleKey,

        failed_submission_id:
          failedSubmissionId,

        external_operation_id:
          externalOperationId,

        recovery_reason:
          recoveryReason,
      },
    },
  ];
}

if (triggerSource === 'wf01') {
  rejectUnknownFields(
    input,
    new Set([
      'case_id',
      'correlation_id',
      'trigger_source',
      'request_cycle_key',
    ]),
  );

  const requestCycleKey = requiredText(
    input.request_cycle_key,
    'request_cycle_key',
    200,
  );

  if (requestCycleKey !== 'initial') {
    throw new Error(
      'WF01 request_cycle_key must equal initial',
    );
  }

  return buildOutput({
    invocationKind: 'initial_request',
    requestCycleKey: 'initial',
  });
}

if (triggerSource === 'wf03') {
  rejectUnknownFields(
    input,
    new Set([
      'case_id',
      'correlation_id',
      'trigger_source',
      'request_cycle_key',
      'failed_submission_id',
    ]),
  );

  const failedSubmissionId =
    requiredUuid(
      input.failed_submission_id,
      'failed_submission_id',
    );

  const requestCycleKey = requiredText(
    input.request_cycle_key,
    'request_cycle_key',
    200,
  );

  const expectedRequestCycleKey =
    `validation_failed:${failedSubmissionId}`;

  if (
    requestCycleKey !==
    expectedRequestCycleKey
  ) {
    throw new Error(
      'WF03 request_cycle_key does not match failed_submission_id',
    );
  }

  return buildOutput({
    invocationKind:
      'correction_request',

    requestCycleKey,
    failedSubmissionId,
  });
}

if (triggerSource !== 'wf98') {
  throw new Error(
    `Unsupported trigger_source: ${triggerSource}`,
  );
}

const hasExternalOperationId =
  hasOwn(
    input,
    'external_operation_id',
  );

const hasRecoveryReason =
  hasOwn(
    input,
    'recovery_reason',
  );

if (
  hasExternalOperationId ===
  hasRecoveryReason
) {
  throw new Error(
    'WF98 input must contain exactly one of external_operation_id or recovery_reason',
  );
}

if (hasExternalOperationId) {
  rejectUnknownFields(
    input,
    new Set([
      'case_id',
      'correlation_id',
      'trigger_source',
      'external_operation_id',
    ]),
  );

  const externalOperationId =
    requiredUuid(
      input.external_operation_id,
      'external_operation_id',
    );

  return buildOutput({
    invocationKind:
      'operation_retry',

    externalOperationId,
  });
}

const recoveryReason = requiredText(
  input.recovery_reason,
  'recovery_reason',
  100,
);

if (
  recoveryReason ===
  'missing_initial_dispatch'
) {
  rejectUnknownFields(
    input,
    new Set([
      'case_id',
      'correlation_id',
      'trigger_source',
      'recovery_reason',
      'request_cycle_key',
    ]),
  );

  const requestCycleKey = requiredText(
    input.request_cycle_key,
    'request_cycle_key',
    200,
  );

  if (requestCycleKey !== 'initial') {
    throw new Error(
      'WF98 initial recovery request_cycle_key must equal initial',
    );
  }

  return buildOutput({
    invocationKind:
      'missing_initial_dispatch',

    requestCycleKey: 'initial',
    recoveryReason,
  });
}

if (
  recoveryReason ===
  'missing_correction_dispatch'
) {
  rejectUnknownFields(
    input,
    new Set([
      'case_id',
      'correlation_id',
      'trigger_source',
      'recovery_reason',
      'request_cycle_key',
      'failed_submission_id',
    ]),
  );

  const failedSubmissionId =
    requiredUuid(
      input.failed_submission_id,
      'failed_submission_id',
    );

  const requestCycleKey = requiredText(
    input.request_cycle_key,
    'request_cycle_key',
    200,
  );

  const expectedRequestCycleKey =
    `validation_failed:${failedSubmissionId}`;

  if (
    requestCycleKey !==
    expectedRequestCycleKey
  ) {
    throw new Error(
      'WF98 correction recovery request_cycle_key does not match failed_submission_id',
    );
  }

  return buildOutput({
    invocationKind:
      'missing_correction_dispatch',

    requestCycleKey,
    failedSubmissionId,
    recoveryReason,
  });
}

throw new Error(
  `Unsupported WF98 recovery_reason: ${recoveryReason}`,
);

// WF02 validates protected runtime configuration.
//
// Secret values are validated but must never be returned
// in workflow output or retained in execution data.

function requiredText(
  name,
  maxLength = 200,
) {
  const rawValue = $env[name];

  if (
    rawValue === null ||
    rawValue === undefined
  ) {
    throw new Error(
      `${name} is required`,
    );
  }

  const value = String(rawValue).trim();

  if (!value) {
    throw new Error(
      `${name} must not be blank`,
    );
  }

  if (value.length > maxLength) {
    throw new Error(
      `${name} exceeds ${maxLength} characters`,
    );
  }

  return value;
}

function optionalText(
  name,
  maxLength = 320,
) {
  const rawValue = $env[name];

  if (
    rawValue === null ||
    rawValue === undefined ||
    String(rawValue).trim() === ''
  ) {
    return null;
  }

  const value = String(rawValue).trim();

  if (value.length > maxLength) {
    throw new Error(
      `${name} exceeds ${maxLength} characters`,
    );
  }

  return value;
}

function boundedInteger(
  name,
  fallback,
  minimum,
  maximum,
) {
  const rawValue = $env[name];

  const value =
    rawValue === null ||
    rawValue === undefined ||
    String(rawValue).trim() === ''
      ? fallback
      : Number(rawValue);

  if (
    !Number.isInteger(value) ||
    value < minimum ||
    value > maximum
  ) {
    throw new Error(
      `${name} must be an integer between ${minimum} and ${maximum}`,
    );
  }

  return value;
}

function decodeEncryptionKey(rawValue) {
  const trimmed = rawValue.trim();

  if (!trimmed) {
    throw new Error(
      'CLIENT_DATA_TOKEN_ENCRYPTION_KEY must not be blank',
    );
  }

  const normalized = trimmed
    .replace(/-/g, '+')
    .replace(/_/g, '/');

  if (
    !/^[A-Za-z0-9+/]*={0,2}$/.test(
      normalized,
    )
  ) {
    throw new Error(
      'CLIENT_DATA_TOKEN_ENCRYPTION_KEY must use Base64 or Base64URL encoding',
    );
  }

  if (normalized.length % 4 === 1) {
    throw new Error(
      'CLIENT_DATA_TOKEN_ENCRYPTION_KEY has invalid Base64 length',
    );
  }

  const padded =
    normalized +
    '='.repeat(
      (4 - (normalized.length % 4)) % 4,
    );

  const keyBytes = Buffer.from(
    padded,
    'base64',
  );

  const canonicalValue = keyBytes
    .toString('base64')
    .replace(/=+$/g, '');

  const suppliedValue = normalized
    .replace(/=+$/g, '');

  if (canonicalValue !== suppliedValue) {
    throw new Error(
      'CLIENT_DATA_TOKEN_ENCRYPTION_KEY is not valid canonical Base64 data',
    );
  }

  if (keyBytes.length !== 32) {
    throw new Error(
      'CLIENT_DATA_TOKEN_ENCRYPTION_KEY must decode to exactly 32 bytes',
    );
  }
}

const formBaseUrl = requiredText(
  'CLIENT_DATA_FORM_BASE_URL',
  2000,
);

const absoluteUrlMatch = formBaseUrl.match(
  /^(https?):\/\/([^/?#]+)(\/[^?#]*)?(\?[^#]*)?$/i,
);

if (!absoluteUrlMatch) {
  throw new Error(
    'CLIENT_DATA_FORM_BASE_URL must be a valid absolute HTTP or HTTPS URL',
  );
}

const protocol =
  absoluteUrlMatch[1].toLowerCase();

const authority =
  absoluteUrlMatch[2];

const pathname =
  absoluteUrlMatch[3] ?? '/';

const query =
  absoluteUrlMatch[4] ?? '';

if (authority.includes('@')) {
  throw new Error(
    'CLIENT_DATA_FORM_BASE_URL must not contain credentials',
  );
}

let hostname;

if (authority.startsWith('[')) {
  const closingBracket =
    authority.indexOf(']');

  if (closingBracket === -1) {
    throw new Error(
      'CLIENT_DATA_FORM_BASE_URL contains an invalid hostname',
    );
  }

  hostname = authority
    .slice(1, closingBracket)
    .toLowerCase();
} else {
  hostname = authority
    .split(':')[0]
    .toLowerCase();
}

if (!hostname) {
  throw new Error(
    'CLIENT_DATA_FORM_BASE_URL contains an invalid hostname',
  );
}

const localHosts = new Set([
  'localhost',
  '127.0.0.1',
  '::1',
]);

if (
  protocol !== 'https' &&
  !localHosts.has(hostname)
) {
  throw new Error(
    'CLIENT_DATA_FORM_BASE_URL must use HTTPS outside localhost',
  );
}

if (formBaseUrl.includes('#')) {
  throw new Error(
    'CLIENT_DATA_FORM_BASE_URL must not contain a URL fragment',
  );
}

if (
  /(?:^\?|&)token(?:=|&|$)/i.test(
    query,
  )
) {
  throw new Error(
    'CLIENT_DATA_FORM_BASE_URL must not already contain a token parameter',
  );
}

if (
  /\/form-test(?:\/|$)/i.test(
    pathname,
  )
) {
  throw new Error(
    'CLIENT_DATA_FORM_BASE_URL must not use an n8n test form URL',
  );
}

if (
  !/\/form(?:\/|$)/i.test(
    pathname,
  )
) {
  throw new Error(
    'CLIENT_DATA_FORM_BASE_URL must point to an n8n production Form URL',
  );
}

const tokenTtlHours = boundedInteger(
  'CLIENT_DATA_FORM_TOKEN_TTL_HOURS',
  72,
  1,
  720,
);

const operationLeaseSeconds =
  boundedInteger(
    'WF02_OPERATION_LEASE_SECONDS',
    300,
    30,
    3600,
  );

const operationMaxAttempts =
  boundedInteger(
    'WF02_OPERATION_MAX_ATTEMPTS',
    5,
    1,
    20,
  );

const encryptionKeyId = requiredText(
  'CLIENT_DATA_TOKEN_ENCRYPTION_KEY_ID',
  120,
);

if (
  !/^[A-Za-z0-9._:-]+$/.test(
    encryptionKeyId,
  )
) {
  throw new Error(
    'CLIENT_DATA_TOKEN_ENCRYPTION_KEY_ID contains unsupported characters',
  );
}

const encryptionKeyRaw = requiredText(
  'CLIENT_DATA_TOKEN_ENCRYPTION_KEY',
  500,
);

// Validate the secret without returning it.
decodeEncryptionKey(
  encryptionKeyRaw,
);

const senderName = requiredText(
  'CLIENT_DATA_REQUEST_SENDER_NAME',
  120,
);

const supportContact = optionalText(
  'CLIENT_DATA_SUPPORT_CONTACT',
  320,
);

return {
  json: {
    ...$json,

    configuration: {
      form_base_url:
        formBaseUrl,

      token_ttl_hours:
        tokenTtlHours,

      token_ttl_seconds:
        tokenTtlHours * 60 * 60,

      encryption_key_id:
        encryptionKeyId,

      operation_lease_seconds:
        operationLeaseSeconds,

      operation_max_attempts:
        operationMaxAttempts,

      sender_name:
        senderName,

      support_contact:
        supportContact,
    },

    configuration_validated: true,

    configuration_validated_at:
      new Date().toISOString(),
  },
};

// WF02 validates authoritative context loaded from PostgreSQL.
//
// This node performs no database writes and no external calls.
// It returns one deterministic routing decision:
// - ready
// - not_required
// - invalid_internal_invocation

const input = $json ?? {};

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function isUuid(value) {
  return (
    typeof value === 'string' &&
    UUID_PATTERN.test(value.trim())
  );
}

function normalizedText(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const normalized =
    String(value).trim();

  return normalized || null;
}

function invalid(
  errorCode,
  errorMessage,
  errorClass =
    'invalid_internal_invocation',
) {
  return {
    json: {
      ...input,

      context_decision:
        'invalid_internal_invocation',

      context_valid: false,
      business_action_required: false,

      error_class:
        errorClass,

      error_code:
        errorCode,

      error_message:
        errorMessage,

      retryable: false,
      severity: 'critical',
      requires_intervention: true,

      resolved_request_cycle_key:
        null,

      resolved_failed_submission_id:
        null,

      resolved_external_operation_id:
        input
          .authoritative_external_operation_id ??
        null,

      validated_at:
        new Date().toISOString(),
    },
  };
}

function notRequired(reason) {
  return {
    json: {
      ...input,

      context_decision:
        'not_required',

      context_valid: true,
      business_action_required: false,

      result:
        'not_required',

      not_required_reason:
        reason,

      error_class: null,
      error_code: null,
      error_message: null,

      retryable: false,
      severity: null,
      requires_intervention: false,

      resolved_request_cycle_key:
        null,

      resolved_failed_submission_id:
        null,

      resolved_external_operation_id:
        input
          .authoritative_external_operation_id ??
        null,

      validated_at:
        new Date().toISOString(),
    },
  };
}

function ready({
  requestCycleKey,
  failedSubmissionId = null,
  externalOperationId = null,
  cycleMode,
  expectedTemplateKey,
}) {
  return {
    json: {
      ...input,

      context_decision:
        'ready',

      context_valid: true,
      business_action_required: true,

      result: null,
      not_required_reason: null,

      error_class: null,
      error_code: null,
      error_message: null,

      retryable: false,
      severity: null,
      requires_intervention: false,

      resolved_request_cycle_key:
        requestCycleKey,

      resolved_failed_submission_id:
        failedSubmissionId,

      resolved_external_operation_id:
        externalOperationId,

      cycle_mode:
        cycleMode,

      expected_template_key:
        expectedTemplateKey,

      validated_at:
        new Date().toISOString(),
    },
  };
}

const invocationKind =
  normalizedText(
    input.invocation_kind,
  );

const caseState =
  normalizedText(
    input.authoritative_case_state,
  );

if (input.case_found !== true) {
  return invalid(
    'case_not_found',
    'WF02 could not load the referenced onboarding case',
    'data_integrity_failure',
  );
}

if (
  !isUuid(
    input.authoritative_case_id,
  )
) {
  return invalid(
    'invalid_authoritative_case_id',
    'WF02 loaded an invalid authoritative case identifier',
    'data_integrity_failure',
  );
}

if (
  !isUuid(
    input.authoritative_correlation_id,
  )
) {
  return invalid(
    'invalid_authoritative_correlation_id',
    'WF02 loaded an invalid authoritative correlation identifier',
    'data_integrity_failure',
  );
}

if (
  input.supplied_case_id !==
  input.authoritative_case_id
) {
  return invalid(
    'case_identity_mismatch',
    'Supplied case identifier does not match the authoritative case',
    'data_integrity_failure',
  );
}

if (
  input.supplied_correlation_id !==
  input.authoritative_correlation_id
) {
  return invalid(
    'correlation_id_mismatch',
    'Supplied correlation identifier does not match the authoritative case',
    'data_integrity_failure',
  );
}

if (
  input.collect_step_found !== true ||
  !isUuid(input.collect_step_id)
) {
  return invalid(
    'collect_client_data_step_not_found',
    'The authoritative collect_client_data step is missing',
    'persisted_data_inconsistency',
  );
}

const intakeContactEmail =
  normalizedText(
    input.intake_contact_email,
  );

if (!intakeContactEmail) {
  return invalid(
    'intake_contact_email_missing',
    'The authoritative intake contact email is missing',
    'persisted_data_inconsistency',
  );
}

const advancedStates = new Set([
  'data_received',
  'awaiting_approval',
  'rejected',
  'approved',
  'provisioning',
  'provisioning_failed',
  'provisioned',
  'finalizing',
  'finalization_failed',
  'completed',
]);

if (
  invocationKind ===
    'correction_request' ||
  invocationKind ===
    'missing_correction_dispatch'
) {
  if (
    input.failed_submission_found !==
    true
  ) {
    return invalid(
      'failed_submission_not_found',
      'WF02 could not load the referenced failed submission',
      'data_integrity_failure',
    );
  }

  if (
    input.failed_submission_case_id !==
    input.authoritative_case_id
  ) {
    return invalid(
      'failed_submission_case_mismatch',
      'The failed submission does not belong to the authoritative case',
      'data_integrity_failure',
    );
  }

  if (
    input
      .failed_submission_validation_status !==
    'failed'
  ) {
    return invalid(
      'submission_not_failed',
      'The referenced submission is not in failed validation status',
      'data_integrity_failure',
    );
  }

  if (
    input
      .authoritative_failed_submission_id !==
    input.supplied_failed_submission_id
  ) {
    return invalid(
      'failed_submission_identity_mismatch',
      'The supplied failed submission does not match the authoritative submission',
      'data_integrity_failure',
    );
  }

  const expectedCycleKey =
    `validation_failed:${input.authoritative_failed_submission_id}`;

  if (
    input
      .supplied_request_cycle_key !==
    expectedCycleKey
  ) {
    return invalid(
      'request_cycle_key_mismatch',
      'The correction request cycle does not match the failed submission',
      'data_integrity_failure',
    );
  }

  if (
    advancedStates.has(caseState)
  ) {
    return notRequired(
      `case_already_advanced:${caseState}`,
    );
  }

  if (
    caseState !==
      'validation_failed' &&
    caseState !==
      'awaiting_client_data'
  ) {
    return invalid(
      'invalid_correction_case_state',
      `Correction request is not valid while case state is ${caseState}`,
    );
  }

  return ready({
    requestCycleKey:
      expectedCycleKey,

    failedSubmissionId:
      input
        .authoritative_failed_submission_id,

    externalOperationId:
      null,

    cycleMode:
      caseState ===
      'awaiting_client_data'
        ? 'verify_existing_delivery'
        : 'prepare_correction_cycle',

    expectedTemplateKey:
      'client_data_correction_v1',
  });
}

if (
  invocationKind ===
  'operation_retry'
) {
  if (
    input.external_operation_found !==
    true
  ) {
    return invalid(
      'external_operation_not_found',
      'WF02 could not load the referenced external operation',
      'data_integrity_failure',
    );
  }

  if (
    input.operation_case_id !==
    input.authoritative_case_id
  ) {
    return invalid(
      'external_operation_case_mismatch',
      'The external operation does not belong to the authoritative case',
      'data_integrity_failure',
    );
  }

  if (
    input.operation_type !==
    'send_client_data_request'
  ) {
    return invalid(
      'external_operation_type_mismatch',
      'The external operation is not a send_client_data_request operation',
      'data_integrity_failure',
    );
  }

  if (
    input
      .authoritative_external_operation_id !==
    input.supplied_external_operation_id
  ) {
    return invalid(
      'external_operation_identity_mismatch',
      'The supplied external operation does not match the authoritative operation',
      'data_integrity_failure',
    );
  }

  const operationTokenId =
    normalizedText(
      input.operation_token_id,
    );

  if (!isUuid(operationTokenId)) {
    return invalid(
      'operation_token_id_invalid',
      'The external operation summary does not contain a valid token identifier',
      'persisted_data_inconsistency',
    );
  }

  const operationCycleKey =
    normalizedText(
      input.operation_request_cycle_key,
    );

