// WF02 decrypts an existing issued form token.
//
// Encrypted fields are removed from the output immediately.
// On failure, the node returns only sanitized error metadata.

const {
  createDecipheriv,
  createHash,
  timingSafeEqual,
} = require('crypto');

const input = $json ?? {};

const {
  authoritative_token_hash_base64:
    tokenHashBase64,

  authoritative_token_ciphertext_base64:
    tokenCiphertextBase64,

  authoritative_token_nonce_base64:
    tokenNonceBase64,

  authoritative_token_auth_tag_base64:
    tokenAuthTagBase64,

  authoritative_encryption_key_id:
    persistedEncryptionKeyId,

  ephemeral_plain_token:
    ignoredPlainToken,

  ...safeInput
} = input;

function fail(code) {
  const error = new Error(code);
  error.failureCode = code;
  throw error;
}

function requireText(
  value,
  fieldName,
  maxLength = 500,
) {
  if (
    value === null ||
    value === undefined
  ) {
    fail(`${fieldName}_missing`);
  }

  const normalized =
    String(value).trim();

  if (
    !normalized ||
    normalized.length > maxLength
  ) {
    fail(`${fieldName}_invalid`);
  }

  return normalized;
}

function decodeStoredBase64(
  value,
  fieldName,
  expectedLength,
) {
  const encoded =
    requireText(
      value,
      fieldName,
      500,
    ).replace(/\s+/g, '');

  if (
    !/^[A-Za-z0-9+/]+={0,2}$/.test(encoded)
  ) {
    fail(`${fieldName}_invalid_base64`);
  }

  const decoded =
    Buffer.from(
      encoded,
      'base64',
    );

  if (decoded.length !== expectedLength) {
    fail(`${fieldName}_invalid_length`);
  }

  return decoded;
}

function decodeRuntimeEncryptionKey(value) {
  const encoded =
    requireText(
      value,
      'runtime_encryption_key',
      200,
    )
      .replace(/\s+/g, '')
      .replace(/-/g, '+')
      .replace(/_/g, '/');

  if (
    !/^[A-Za-z0-9+/]+={0,2}$/.test(encoded)
  ) {
    fail('runtime_encryption_key_invalid_base64');
  }

  const remainder =
    encoded.length % 4;

  const padded =
    remainder === 0
      ? encoded
      : encoded + '='.repeat(4 - remainder);

  const key =
    Buffer.from(
      padded,
      'base64',
    );

  if (key.length !== 32) {
    fail('runtime_encryption_key_invalid_length');
  }

  return key;
}

let failureCode =
  'existing_token_decryption_failed';

try {
  if (
    input.token_prepare_decision !==
    'decrypt_existing_token'
  ) {
    fail('unexpected_token_prepare_decision');
  }

  if (
    input.resolved_token_status !==
    'issued'
  ) {
    fail('existing_token_not_issued');
  }

  const caseId =
    requireText(
      input.resolved_case_id,
      'resolved_case_id',
      36,
    ).toLowerCase();

  const tokenId =
    requireText(
      input.resolved_token_id,
      'resolved_token_id',
      36,
    ).toLowerCase();

  const requestCycleKey =
    requireText(
      input.resolved_request_cycle_key,
      'resolved_request_cycle_key',
      200,
    );

  const configuredEncryptionKeyId =
    requireText(
      $env.CLIENT_DATA_TOKEN_ENCRYPTION_KEY_ID,
      'configured_encryption_key_id',
      120,
    );

  const authoritativeEncryptionKeyId =
    requireText(
      persistedEncryptionKeyId,
      'persisted_encryption_key_id',
      120,
    );

  if (
    authoritativeEncryptionKeyId !==
    configuredEncryptionKeyId
  ) {
    fail('encryption_key_id_mismatch');
  }

  const encryptionKey =
    decodeRuntimeEncryptionKey(
      $env.CLIENT_DATA_TOKEN_ENCRYPTION_KEY,
    );

  const expectedTokenHash =
    decodeStoredBase64(
      tokenHashBase64,
      'token_hash',
      32,
    );

  const ciphertext =
    decodeStoredBase64(
      tokenCiphertextBase64,
      'token_ciphertext',
      32,
    );

  const nonce =
    decodeStoredBase64(
      tokenNonceBase64,
      'token_nonce',
      12,
    );

  const authTag =
    decodeStoredBase64(
      tokenAuthTagBase64,
      'token_auth_tag',
      16,
    );

  const aadText =
    [
      'wf02-form-token',
      'v1',
      caseId,
      tokenId,
      requestCycleKey,
    ].join('|');

  const decipher =
    createDecipheriv(
      'aes-256-gcm',
      encryptionKey,
      nonce,
    );

  decipher.setAAD(
    Buffer.from(
      aadText,
      'utf8',
    ),
  );

  decipher.setAuthTag(authTag);

  const tokenBytes =
    Buffer.concat([
      decipher.update(ciphertext),
      decipher.final(),
    ]);

  if (tokenBytes.length !== 32) {
    fail('decrypted_token_invalid_length');
  }

  const calculatedTokenHash =
    createHash('sha256')
      .update(tokenBytes)
      .digest();

  if (
    !timingSafeEqual(
      expectedTokenHash,
      calculatedTokenHash,
    )
  ) {
    fail('decrypted_token_hash_mismatch');
  }

  return {
    json: {
      ...safeInput,

      ephemeral_plain_token:
        tokenBytes.toString('base64url'),

      token_material_decision:
        'plain_token_ready',

      plain_token_source:
        'decrypted_existing_token',

      token_material_error_class:
        null,

      token_material_error_code:
        null,

      token_material_error_message:
        null,

      token_material_requires_intervention:
        false,

      existing_form_token_decrypted:
        true,
    },
  };
} catch (error) {
  failureCode =
    typeof error?.failureCode === 'string'
      ? error.failureCode
      : failureCode;

  return {
    json: {
      ...safeInput,

      ephemeral_plain_token:
        null,

      token_material_decision:
        'invalid_token_material',

      plain_token_source:
        null,

      token_material_error_class:
        'token_decryption_failure',

      token_material_error_code:
        failureCode,

      token_material_error_message:
        'WF02 could not authenticate and decrypt the existing form token',

      token_material_requires_intervention:
        true,

      existing_form_token_decrypted:
        false,
    },
  };
}

// WF02 validates the newly generated plain token
// and normalizes it to the shared token-material contract.
//
// The node never throws an error containing token material.

const input = $json ?? {};

const {
  ephemeral_plain_token: plainToken,
  ...safeInput
} = input;

let tokenBytes = null;

try {
  if (
    typeof plainToken === 'string' &&
    /^[A-Za-z0-9_-]{43}$/.test(plainToken)
