  input.token_prepare_decision ===
    'use_generated_token' &&
  input.token_created === true &&
  input.resolved_token_status ===
    'issued' &&
  typeof input.resolved_token_id ===
    'string' &&
  tokenBytes !== null &&
  tokenBytes.length === 32;

if (!tokenIsValid) {
  return {
    json: {
      ...safeInput,

      ephemeral_plain_token:
        null,

      token_material_decision:
        'invalid_token_material',

      plain_token_source:
        null,

      token_material_error_class:
        'data_integrity_failure',

      token_material_error_code:
        'generated_token_material_invalid',

