        'WF02 generated token material is incomplete or inconsistent with the authoritative token',

      token_material_requires_intervention:
        true,

      generated_form_token_ready:
        false,
    },
  };
}

return {
  json: {
    ...safeInput,

    ephemeral_plain_token:
      plainToken,

    token_material_decision:
      'plain_token_ready',

    plain_token_source:
      'generated_new_token',

    token_material_error_class:
      null,

    token_material_error_code:
      null,

    token_material_error_message:
      null,

    token_material_requires_intervention:
      false,

    generated_form_token_ready:
      true,
  },
};

