    retryable:
      false,

    severity:
      'critical',

    requires_intervention:
      true,

    error_details: {
      invocation_kind:
        safeText(
          input.invocation_kind,
          100,
        ),

      trigger_source:
        safeText(
          input.trigger_source,
          50,
        ),

      request_mode:
        safeText(
          input.resolved_request_mode,
          100,
        ),

      request_cycle_key:
        safeText(
          input.resolved_request_cycle_key,
          200,
        ),

      token_prepare_outcome:
        safeText(
          input.token_prepare_outcome,
