  const normalized = String(value)
    .replace(
      /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g,
      ' ',
    )
    .replace(/\s+/g, ' ')
    .trim();

  return normalized
    ? normalized.slice(0, maximumLength)
    : null;
}

const {
  ephemeral_plain_token:
    ignoredPlainToken,

  authoritative_token_hash_base64:
    ignoredTokenHash,

  authoritative_token_ciphertext_base64:
    ignoredTokenCiphertext,

  authoritative_token_nonce_base64:
    ignoredTokenNonce,

  authoritative_token_auth_tag_base64:
    ignoredTokenAuthTag,

  authoritative_encryption_key_id:
    ignoredEncryptionKeyId,

  ...context
} = input;

const failureCode =
  safeText(
    input.token_material_error_code ??
    input.claimed_token_material_error_code,
    150,
  ) ??
  'token_material_unavailable';

const failureMessage =
  safeText(
    input.token_material_error_message ??
    input.claimed_token_material_error_message,
    1000,
  ) ??
  'WF02 could not safely resolve token material after claiming the delivery operation';

