    input.authoritative_operation_id ??
      input.resolved_external_operation_id,
    'external_operation_id',
  );

const requestCycleKey =
  requireText(
    input.authoritative_request_cycle_key ??
      input.resolved_request_cycle_key,
    'request_cycle_key',
    200,
  );

const operationStatus =
