if (caseState !== 'awaiting_client_data') {
  throw new Error(
    'Already-delivered case must have state awaiting_client_data',
  );
}

const result =
  input.delivery_result_intent ===
    'delivered'
    ? 'delivered'
    : 'already_delivered';

return {
  json: {
    workflow:
      'WF02',

    result,

    case_id:
      caseId,

    correlation_id:
      correlationId,

    request_cycle_key:
      requestCycleKey,

    token_id:
      tokenId,

    external_operation_id:
      externalOperationId,

    operation_status:
      operationStatus,

    case_state:
      caseState,
  },
};

