const input = $json ?? {};

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function requireUuid(value, fieldName) {
  if (typeof value !== 'string') {
    throw new Error(
      `${fieldName} must be a UUID string`,
    );
  }

  const normalized =
    value.trim().toLowerCase();

  if (!UUID_PATTERN.test(normalized)) {
    throw new Error(
      `${fieldName} must be a valid UUID`,
    );
  }

  return normalized;
}

function requireText(
  value,
  fieldName,
  maxLength = 320,
) {
  if (
    value === null ||
    value === undefined
  ) {
    throw new Error(
      `${fieldName} is required`,
    );
  }

  const normalized = String(value)
    .replace(
      /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g,
      ' ',
    )
    .trim();

  if (!normalized) {
    throw new Error(
      `${fieldName} must not be blank`,
    );
  }

  if (normalized.length > maxLength) {
    throw new Error(
      `${fieldName} exceeds ${maxLength} characters`,
    );
  }

  return normalized;
}

function requirePositiveInteger(
  value,
  fieldName,
  maximum,
) {
  const normalized =
    Number(value);

  if (
    !Number.isInteger(normalized) ||
    normalized < 1 ||
    normalized > maximum
  ) {
    throw new Error(
      `${fieldName} must be an integer between 1 and ${maximum}`,
    );
  }

  return normalized;
}

const tokenClaimMaterialDecision =
  requireText(
    input.token_material_decision,
    'token_material_decision',
    100,
  );

if (
  ![
    'plain_token_ready',
    'encrypted_token_ready_for_claim',
    'expired_token_ready_for_claim',
  ].includes(tokenClaimMaterialDecision)
) {
  throw new Error(
    'Build Operation Identity received unsupported token material state',
  );
}

const caseId =
  requireUuid(
    input.resolved_case_id,
    'resolved_case_id',
  );

const correlationId =
  requireUuid(
    input.resolved_correlation_id,
    'resolved_correlation_id',
  );

const tokenId =
  requireUuid(
    input.resolved_token_id,
    'resolved_token_id',
  );

const requestCycleKey =
  requireText(
    input.resolved_request_cycle_key,
    'resolved_request_cycle_key',
    200,
  );

const recipientEmail =
  requireText(
    input.resolved_recipient_email,
    'resolved_recipient_email',
    320,
  ).toLowerCase();

const templateKey =
  requireText(
    input.resolved_template_key,
    'resolved_template_key',
    100,
  );

const leaseOwner =
  requireText(
    input.lease_owner,
    'lease_owner',
    200,
  );

const leaseSeconds =
  requirePositiveInteger(
    input.operation_lease_seconds,
    'operation_lease_seconds',
    86400,
  );

const maximumAttempts =
  requirePositiveInteger(
    input.operation_max_attempts,
    'operation_max_attempts',
    100,
  );

if (
  requestCycleKey === 'initial' &&
  templateKey !== 'client_data_request_v1'
) {
  throw new Error(
    'Initial request cycle requires client_data_request_v1',
  );
}

if (
  requestCycleKey.startsWith(
    'validation_failed:',
  ) &&
  templateKey !== 'client_data_correction_v1'
) {
  throw new Error(
    'Correction request cycle requires client_data_correction_v1',
  );
}

if (
  requestCycleKey !== 'initial' &&
  !requestCycleKey.startsWith(
    'validation_failed:',
  )
) {
  throw new Error(
    'Unsupported request cycle key',
  );
}

const operationType =
  'send_client_data_request';

const idempotencyKey =
  [
    'onboarding',
    caseId,
    'form-token',
    tokenId,
    'send-client-data-request',
  ].join(':');

const markerHash =
  createHash('sha256')
    .update(
      Buffer.from(
        idempotencyKey,
        'utf8',
      ),
    )
    .digest('hex');

const messageMarker =
  `b2b-onboarding-${markerHash.slice(0, 24)}`;

const requestSummary = {
  token_id:
    tokenId,

  request_cycle_key:
    requestCycleKey,

  recipient_email:
    recipientEmail,

  template_key:
    templateKey,

  message_marker:
    messageMarker,
};

return {
  json: {
    ...input,

    resolved_case_id:
      caseId,

    resolved_correlation_id:
      correlationId,

    resolved_token_id:
      tokenId,

    resolved_recipient_email:
      recipientEmail,

    resolved_template_key:
      templateKey,

    operation_type:
      operationType,

    operation_idempotency_key:
      idempotencyKey,

    operation_message_marker:
      messageMarker,

    operation_request_summary:
      requestSummary,

    operation_lease_owner:
      leaseOwner,

    operation_claim_lease_seconds:
      leaseSeconds,

    operation_claim_max_attempts:
      maximumAttempts,

    operation_identity_built:
      true,
  },
};

// WF02 normalizes and validates the result returned by
// claim_external_operation.
//
// The plain token is retained only when the current execution
// successfully owns the operation lease.

const row = $json ?? {};

const inputContext =
  row.input_context &&
  typeof row.input_context === 'object' &&
  !Array.isArray(row.input_context)
    ? row.input_context
    : {};

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function optionalUuid(value) {
  if (typeof value !== 'string') {
    return null;
  }

  const normalized =
    value.trim().toLowerCase();

  return UUID_PATTERN.test(normalized)
    ? normalized
    : null;
}

function safeText(value, maxLength = 500) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const normalized = String(value)
    .replace(
      /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g,
      ' ',
    )
    .replace(/\s+/g, ' ')
    .trim();

  if (!normalized) {
    return null;
  }

  return normalized.slice(0, maxLength);
}

function optionalInteger(value) {
  const normalized =
    Number(value);

  return Number.isInteger(normalized)
    ? normalized
    : null;
}

function isJsonObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

const {
  input_context:
    ignoredInputContext,

  ...claimRow
} = row;

const {
  ephemeral_plain_token:
    plainToken,

  authoritative_token_hash_base64:
    ignoredTokenHash,

  authoritative_token_ciphertext_base64:
    ignoredTokenCiphertext,

  authoritative_token_nonce_base64:
    ignoredTokenNonce,

  authoritative_token_auth_tag_base64:
    ignoredTokenAuthTag,

  authoritative_encryption_key_id:
    ignoredEncryptionKeyId,

  ...safeInputContext
} = inputContext;

const operationId =
  optionalUuid(
    claimRow.operation_id,
  );

const expectedRetryOperationId =
  safeInputContext.resolved_request_mode ===
    'retry_existing_operation'
    ? optionalUuid(
        safeInputContext.resolved_external_operation_id,
      )
    : null;

const claimOutcome =
  safeText(
    claimRow.claim_outcome,
    100,
  );

const operationStatus =
  safeText(
    claimRow.operation_status,
    50,
  );

const currentAttemptCount =
  optionalInteger(
    claimRow.current_attempt_count,
  );

const configuredMaxAttempts =
  optionalInteger(
    claimRow.configured_max_attempts,
  );

const currentLeaseExpiresAt =
  safeText(
    claimRow.current_lease_expires_at,
    100,
  );

const currentExternalId =
  safeText(
    claimRow.current_external_id,
    500,
  );

const currentResponseSummary =
  isJsonObject(
    claimRow.current_response_summary,
  )
    ? claimRow.current_response_summary
    : {};

let claimAction =
  'invalid_claim_state';

let claimValid =
  false;

let errorCode =
  null;

let errorMessage =
  null;

function invalidate(code, message) {
  claimAction =
    'invalid_claim_state';

  claimValid =
    false;

  errorCode =
    code;

  errorMessage =
    message;
}

if (!operationId) {
  invalidate(
    'operation_id_invalid',
    'PostgreSQL did not return a valid external operation ID',
  );
} else if (
  safeInputContext.resolved_request_mode ===
    'retry_existing_operation' &&
  (
    !expectedRetryOperationId ||
    expectedRetryOperationId !== operationId
  )
) {
  invalidate(
    'retry_operation_identity_mismatch',
    'The claimed operation does not match the immutable WF98 retry operation ID',
  );
} else if (!claimOutcome) {
  invalidate(
    'claim_outcome_missing',
    'PostgreSQL did not return an external operation claim outcome',
  );
} else if (
  currentAttemptCount === null ||
  currentAttemptCount < 0
) {
  invalidate(
    'attempt_count_invalid',
    'PostgreSQL returned an invalid external operation attempt count',
  );
} else if (
  configuredMaxAttempts === null ||
  configuredMaxAttempts < 1
) {
  invalidate(
    'max_attempts_invalid',
    'PostgreSQL returned an invalid external operation maximum attempt count',
  );
} else if (
  currentAttemptCount >
  configuredMaxAttempts
) {
  invalidate(
    'attempt_count_exceeds_maximum',
    'External operation attempt count exceeds its configured maximum',
  );
} else {
  switch (claimOutcome) {
    case 'claimed': {
      const plainTokenValid =
        typeof plainToken === 'string' &&
        /^[A-Za-z0-9_-]{43}$/.test(
          plainToken,
        );

      if (
        operationStatus !==
        'in_progress'
      ) {
        invalidate(
          'claimed_operation_not_in_progress',
          'A claimed external operation must have status in_progress',
        );
      } else if (
        currentAttemptCount < 1
      ) {
        invalidate(
          'claimed_attempt_count_invalid',
          'A claimed external operation must have at least one attempt',
        );
      } else if (
        !currentLeaseExpiresAt ||
        Number.isNaN(
          Date.parse(
            currentLeaseExpiresAt,
          ),
        )
      ) {
        invalidate(
          'claimed_lease_missing',
          'A claimed external operation must have a valid lease expiry',
        );
      } else if (!plainTokenValid) {
        invalidate(
          'claimed_plain_token_missing',
          'A claimed external operation requires valid plain token material',
        );
      } else {
        claimAction =
          'reconcile_or_send';

        claimValid =
          true;
      }

      break;
    }

    case 'reuse_succeeded': {
      if (
        operationStatus !==
        'succeeded'
      ) {
        invalidate(
          'reused_operation_not_succeeded',
          'A reused successful operation must have status succeeded',
        );
      } else if (!currentExternalId) {
        invalidate(
          'reused_operation_message_id_missing',
          'A reused successful Gmail operation must contain a message ID',
        );
      } else {
        claimAction =
          'verify_reuse_succeeded';

        claimValid =
          true;
      }

      break;
    }

    case 'busy': {
      if (
        operationStatus !==
        'in_progress'
      ) {
        invalidate(
          'busy_operation_not_in_progress',
          'A busy external operation must have status in_progress',
        );
      } else if (
        !currentLeaseExpiresAt
      ) {
        invalidate(
          'busy_operation_lease_missing',
          'A busy external operation must contain a lease expiry',
        );
      } else {
        claimAction =
          'return_busy';

        claimValid =
          true;
      }

      break;
    }

    case 'not_due': {
      if (
        operationStatus !==
        'failed_retryable'
      ) {
        invalidate(
          'not_due_operation_status_invalid',
          'A not-due operation must have status failed_retryable',
        );
      } else {
        claimAction =
          'return_not_due';

        claimValid =
          true;
      }

      break;
    }

    case 'refused_terminal': {
      if (
        operationStatus !==
        'failed_terminal'
      ) {
        invalidate(
          'terminal_operation_status_invalid',
          'A terminally refused operation must have status failed_terminal',
        );
      } else {
        claimAction =
          'return_failed_terminal';

        claimValid =
          true;
      }

      break;
    }

    case 'refused_exhausted': {
      if (
        currentAttemptCount <
        configuredMaxAttempts
      ) {
        invalidate(
          'exhausted_attempt_count_invalid',
          'An exhausted operation has not reached its maximum attempt count',
        );
      } else {
        claimAction =
          'finalize_exhausted';

        claimValid =
          true;
      }

      break;
    }

    default: {
      invalidate(
        'unsupported_claim_outcome',
        `WF02 received an unsupported external operation claim outcome: ${claimOutcome}`,
      );
    }
  }
}

const output = {
  ...safeInputContext,

  resolved_external_operation_id:
    operationId,

  operation_claim_outcome:
    claimOutcome,

  operation_claim_action:
    claimAction,

  operation_claim_valid:
    claimValid,

  resolved_operation_status:
    operationStatus,

  operation_attempt_count:
    currentAttemptCount,

  operation_configured_max_attempts:
    configuredMaxAttempts,

  operation_lease_expires_at:
    currentLeaseExpiresAt,

  operation_external_id:
    currentExternalId,

  operation_response_summary:
    currentResponseSummary,

  operation_claim_error_class:
    claimValid
      ? null
      : 'data_integrity_failure',

  operation_claim_error_code:
    errorCode,

  operation_claim_error_message:
    errorMessage,

  operation_claim_requires_intervention:
    !claimValid,

  operation_claim_normalized:
    true,
};

/*
 * Only the execution that successfully claimed the lease
 * may retain the plain token and proceed toward Gmail.
