if (
  claimValid &&
  claimAction ===
    'reconcile_or_send'
) {
  output.ephemeral_plain_token =
    plainToken;
}

return {
  json: output,
};

// WF02 builds a sanitized terminal result for claim outcomes
// that must not proceed to Gmail.

const input = $json ?? {};

const action =
  typeof input.operation_claim_action === 'string'
    ? input.operation_claim_action.trim()
    : '';

const operationStatus =
  typeof input.resolved_operation_status === 'string'
    ? input.resolved_operation_status.trim()
    : null;

const configurations = {
  return_busy: {
    result: 'busy',
    expectedStatus: 'in_progress',
  },

  return_not_due: {
    result: 'not_due',
    expectedStatus: 'failed_retryable',
  },

  return_failed_terminal: {
    result: 'failed_terminal',
    expectedStatus: 'failed_terminal',
  },
};

const configuration =
  configurations[action];

if (!configuration) {
  throw new Error(
    `Unsupported non-send claim action: ${action || 'missing'}`,
  );
}

if (
  operationStatus !==
  configuration.expectedStatus
) {
  throw new Error(
    `Claim action ${action} requires operation status ${configuration.expectedStatus}`,
  );
}

const output = {
  workflow:
    'WF02',

  result:
    configuration.result,

  case_id:
    input.resolved_case_id ?? null,

  correlation_id:
    input.resolved_correlation_id ?? null,

  request_cycle_key:
    input.resolved_request_cycle_key ?? null,

  token_id:
    input.resolved_token_id ?? null,

  external_operation_id:
    input.resolved_external_operation_id ?? null,

  operation_status:
    operationStatus,

  attempt_count:
    input.operation_attempt_count ?? null,

  max_attempts:
    input.operation_configured_max_attempts ?? null,
};

if (configuration.result === 'busy') {
  output.lease_expires_at =
    input.operation_lease_expires_at ?? null;
}

return {
  json: output,
};

