  value,
  maximumLength = 500,
) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const normalized =
    String(value)
      .replace(
        /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g,
        ' ',
      )
      .replace(/\s+/g, ' ')
      .trim();

  if (!normalized) {
    return null;
  }

  return normalized.slice(
    0,
    maximumLength,
  );
}

function optionalInteger(value) {
  const normalized =
