  if (typeof value !== 'string') {
    return null;
  }

  const normalized = value.trim().toLowerCase();
  return UUID_PATTERN.test(normalized) ? normalized : null;
}

function safeText(value, maximumLength = 500) {
  if (value === null || value === undefined) {
    return null;
  }

  const normalized = String(value)
    .replace(
      /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g,
      ' ',
    )
    .replace(/\s+/g, ' ')
    .trim();

  return normalized
    ? normalized.slice(0, maximumLength)
    : null;
}

const action =
  safeText(
    input.gmail_failure_finalization_action,
    100,
  );

const retryable =
  action === 'notify_retryable_failure';

const confirmedFailure =
  action === 'notify_retryable_failure' ||
  action === 'notify_terminal_failure';

return {
  json: {
    source_variant: 'explicit_internal',
    source_workflow_name: 'WF02 — Request Client Data',
    source_workflow_id: safeText($workflow.id, 200),
    source_execution_id: safeText($execution.id, 200),

    case_id: optionalUuid(input.resolved_case_id),
    correlation_id: optionalUuid(input.resolved_correlation_id),
    step_id: optionalUuid(input.collect_step_id),
    submission_id: null,
    external_operation_id:
      optionalUuid(input.resolved_external_operation_id),

    error_class: confirmedFailure
      ? (
          safeText(input.gmail_failure_class, 150) ??
          'gmail_delivery_failure'
        )
      : 'data_integrity_failure',

    error_code: confirmedFailure
      ? (
          safeText(input.gmail_failure_class, 150) ??
          'gmail_delivery_failure'
        )
      : (
          safeText(
            input.gmail_failure_finalization_error_code,
            150,
          ) ??
          'invalid_gmail_failure_finalization'
        ),

    error_message: confirmedFailure
      ? (
          safeText(input.gmail_failure_message, 1000) ??
          'Gmail client-data delivery failed'
        )
      : (
          safeText(
            input.gmail_failure_finalization_error_message,
            1000,
          ) ??
          'WF02 received an invalid Gmail failure finalization result'
        ),

    retryable,
    severity: retryable ? 'warning' : 'error',
    requires_intervention:
      action === 'notify_terminal_failure' ||
      !confirmedFailure,

    error_details: {
      stage: 'gmail_delivery_failure',
      finalization_action: action,
      finalization_outcome:
        safeText(
          input.gmail_failure_finalization_outcome,
          100,
        ),
      status_code:
        Number.isInteger(
          Number(input.gmail_failure_status_code),
        )
          ? Number(input.gmail_failure_status_code)
          : null,
      attempt_count:
        Number.isInteger(
          Number(
            input.authoritative_operation_attempt_count ??
            input.operation_attempt_count,
          ),
        )
          ? Number(
              input.authoritative_operation_attempt_count ??
              input.operation_attempt_count,
            )
          : null,
      next_retry_at:
        retryable
          ? safeText(
              input.gmail_failure_next_retry_at,
              100,
            )
          : null,
      request_cycle_key:
        safeText(input.resolved_request_cycle_key, 200),
