// WF02 returns the authoritative result for an operation
// that was already finalized as failed_terminal.
//
// No token material, recipient data, or provider response is returned.

const input = $json ?? {};

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function requireUuid(value, fieldName) {
  if (typeof value !== 'string') {
    throw new Error(`${fieldName} must be a UUID string`);
  }

  const normalized = value.trim().toLowerCase();

  if (!UUID_PATTERN.test(normalized)) {
    throw new Error(`${fieldName} must be a valid UUID`);
  }

  return normalized;
}

function requireText(value, fieldName, maximumLength = 200) {
  if (value === null || value === undefined) {
    throw new Error(`${fieldName} is required`);
  }

  const normalized = String(value).trim();

  if (!normalized) {
    throw new Error(`${fieldName} must not be blank`);
  }

  if (normalized.length > maximumLength) {
    throw new Error(`${fieldName} exceeds ${maximumLength} characters`);
  }

  return normalized;
}

if (
  input.resolved_request_mode !==
  'return_existing_terminal_operation'
) {
  throw new Error(
    'Build Existing Terminal Operation Result received an unsupported request mode',
  );
}

const operationStatus =
  requireText(
    input.operation_status,
    'operation_status',
    100,
  );

if (operationStatus !== 'failed_terminal') {
  throw new Error(
    'Existing terminal operation result requires operation_status=failed_terminal',
  );
}

return {
  json: {
    workflow: 'WF02',
    result: 'failed_terminal',

    case_id:
      requireUuid(
        input.resolved_case_id ??
        input.authoritative_case_id,
        'case_id',
      ),

    correlation_id:
      requireUuid(
        input.resolved_correlation_id ??
        input.authoritative_correlation_id,
        'correlation_id',
      ),

    request_cycle_key:
      requireText(
        input.resolved_request_cycle_key,
        'request_cycle_key',
        200,
      ),

    token_id:
      requireUuid(
        input.resolved_token_id,
        'token_id',
      ),

    external_operation_id:
      requireUuid(
        input.resolved_external_operation_id,
        'external_operation_id',
      ),

    operation_status:
      'failed_terminal',

    case_state:
      requireText(
        input.authoritative_case_state,
        'case_state',
        100,
      ),
  },
};

// WF02 validates that an existing token can be used to build
// and claim the deterministic external operation.
//
// Decryption is intentionally deferred until after the current
// execution owns the operation lease.

const input = $json ?? {};

function requiredText(value, fieldName, maximumLength = 500) {
  if (value === null || value === undefined) {
    throw new Error(`${fieldName} is required`);
  }

  const normalized = String(value).trim();

  if (!normalized) {
    throw new Error(`${fieldName} must not be blank`);
  }

  if (normalized.length > maximumLength) {
    throw new Error(`${fieldName} exceeds ${maximumLength} characters`);
  }

  return normalized;
}

if (
  input.token_prepare_decision !==
  'decrypt_existing_token'
) {
  throw new Error(
    'Prepare Existing Token Claim Context requires token_prepare_decision=decrypt_existing_token',
  );
}

if (input.resolved_token_status !== 'issued') {
  throw new Error(
    'Existing token must remain issued before the operation claim',
  );
}

if (input.token_expired_before_claim === true) {
  return {
    json: {
      ...input,

      ephemeral_plain_token:
        null,

      token_material_decision:
        'expired_token_ready_for_claim',

      plain_token_source:
        null,

      existing_token_claim_context_prepared:
        true,
    },
  };
}

requiredText(
  input.authoritative_token_hash_base64,
  'authoritative_token_hash_base64',
  200,
);

requiredText(
  input.authoritative_token_ciphertext_base64,
  'authoritative_token_ciphertext_base64',
  200,
);

requiredText(
  input.authoritative_token_nonce_base64,
  'authoritative_token_nonce_base64',
  100,
);

requiredText(
  input.authoritative_token_auth_tag_base64,
  'authoritative_token_auth_tag_base64',
  100,
);

requiredText(
  input.authoritative_encryption_key_id,
  'authoritative_encryption_key_id',
  120,
);

return {
  json: {
    ...input,

    ephemeral_plain_token:
      null,

    token_material_decision:
      'encrypted_token_ready_for_claim',

    plain_token_source:
      null,

    existing_token_claim_context_prepared:
      true,
  },
};

// WF02 resolves token material only after the current execution
// successfully claims the external-operation lease.
//
// Generated token material can continue immediately.
// Persisted encrypted material is decrypted only now.
// An already-expired token skips decryption and proceeds only
// to the authoritative expiry finalizer.

const input = $json ?? {};

function hasText(value) {
  return (
    typeof value === 'string' &&
    value.trim() !== ''
  );
}

let action =
  'invalid_claimed_token_material';

let errorCode =
  null;

let errorMessage =
  null;

if (
  input.operation_claim_action !==
    'reconcile_or_send' ||
  input.operation_claim_valid !== true
) {
  errorCode =
    'operation_not_claimed';

  errorMessage =
    'Token material cannot be resolved without a valid operation lease';

} else if (
  input.token_expired_before_claim === true ||
  input.token_material_decision ===
    'expired_token_ready_for_claim'
) {
  action =
    'skip_decryption_for_expiry';

} else if (
  typeof input.ephemeral_plain_token === 'string' &&
  /^[A-Za-z0-9_-]{43}$/.test(
    input.ephemeral_plain_token,
  )
) {
  action =
    'plain_token_ready';

} else if (
  input.token_prepare_decision ===
    'decrypt_existing_token' &&
  hasText(
    input.authoritative_token_hash_base64,
  ) &&
  hasText(
    input.authoritative_token_ciphertext_base64,
  ) &&
  hasText(
    input.authoritative_token_nonce_base64,
  ) &&
  hasText(
    input.authoritative_token_auth_tag_base64,
  ) &&
  hasText(
    input.authoritative_encryption_key_id,
  )
) {
  action =
    'decrypt_existing_token';

} else {
  errorCode =
    'claimed_token_material_incomplete';

  errorMessage =
    'The claimed operation does not contain usable generated or encrypted token material';
}

return {
  json: {
    ...input,

    claimed_token_material_action:
      action,

    claimed_token_material_error_code:
      errorCode,

    claimed_token_material_error_message:
      errorMessage,
  },
};

// WF02 marks the Gmail activity as reconciliation.
//
// This context is fanned out to both the successful search merge
// and the search-error merge so either outcome retains the claimed
// operation identity without retaining mailbox content.

return {
  json: {
    ...($json ?? {}),

    gmail_activity_stage:
      'reconciliation',
  },
};

// WF02 returns the sanitized retryable delivery-failure result.
//
// Retry timing is authoritative PostgreSQL time. The token and
// secure form URL are never returned.

const input = $json ?? {};

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function requireUuid(value, fieldName) {
  if (typeof value !== 'string') {
    throw new Error(`${fieldName} must be a UUID string`);
  }

  const normalized = value.trim().toLowerCase();

  if (!UUID_PATTERN.test(normalized)) {
    throw new Error(`${fieldName} must be a valid UUID`);
  }

  return normalized;
}

function requireText(value, fieldName, maximumLength = 200) {
  if (value === null || value === undefined) {
    throw new Error(`${fieldName} is required`);
  }

  const normalized = String(value).trim();

  if (!normalized) {
    throw new Error(`${fieldName} must not be blank`);
  }

  if (normalized.length > maximumLength) {
    throw new Error(`${fieldName} exceeds ${maximumLength} characters`);
  }

  return normalized;
}

if (
  input.gmail_failure_finalization_action !==
    'return_failed_retryable' ||
  input.gmail_failure_final_operation_status !==
    'failed_retryable'
) {
  throw new Error(
    'Build Retryable Delivery Result requires a finalized failed_retryable operation',
  );
}

return {
  json: {
    workflow:
      'WF02',

    result:
      'failed_retryable',

    case_id:
      requireUuid(
        input.resolved_case_id,
        'case_id',
      ),

    correlation_id:
      requireUuid(
        input.resolved_correlation_id,
        'correlation_id',
      ),

    external_operation_id:
      requireUuid(
        input.resolved_external_operation_id,
        'external_operation_id',
      ),

    operation_status:
      'failed_retryable',

    next_retry_at:
      requireText(
        input.gmail_failure_final_next_retry_at,
        'next_retry_at',
        100,
      ),
  },
};

// WF02 builds one sanitized terminal-failure handoff.
//
// The same item contains a nested WF02 result for the caller and
// a valid explicit_internal payload for WF99. The nested result is
// kept only inside error_details, which WF99 already accepts.

const row = $json ?? {};

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function parseObject(value) {
  if (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  ) {
    return value;
  }

  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);

      return (
        parsed !== null &&
        typeof parsed === 'object' &&
        !Array.isArray(parsed)
      )
        ? parsed
        : {};
    } catch {
      return {};
    }
  }

  return {};
}

function optionalUuid(value) {
  if (typeof value !== 'string') {
    return null;
  }

  const normalized =
    value.trim().toLowerCase();

  return UUID_PATTERN.test(normalized)
    ? normalized
    : null;
}

function safeText(value, maximumLength = 1000) {
  if (value === null || value === undefined) {
    return null;
  }

  const normalized = String(value)
    .replace(
      /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g,
      ' ',
    )
    .replace(/\s+/g, ' ')
    .trim();

  return normalized
    ? normalized.slice(0, maximumLength)
    : null;
}

function optionalInteger(value) {
  const normalized =
    Number(value);

  return Number.isInteger(normalized)
    ? normalized
    : null;
}

const rawContext =
  parseObject(
    row.input_context,
  );

const context =
  Object.keys(rawContext).length > 0
    ? rawContext
    : row;

let stage;
let errorClass;
let errorCode;
let errorMessage;
let operationStatus;
let tokenStatus;
let stepStatus;
let attemptCount;

if (
  row.gmail_failure_finalization_action ===
    'notify_terminal_failure'
) {
  stage =
    safeText(
      row.gmail_activity_stage,
      100,
    ) ??
    'gmail_delivery';

  errorClass =
    safeText(
      row.gmail_failure_final_error_class ??
      row.gmail_failure_class,
      150,
    ) ??
    'gmail_delivery_failure';

  errorCode =
    errorClass;

  errorMessage =
    safeText(
      row.gmail_failure_message,
      1000,
    ) ??
    'Client-data delivery activity was finalized as failed terminal';

  operationStatus =
    row.gmail_failure_final_operation_status;

  tokenStatus =
    row.gmail_failure_final_token_status;

  stepStatus =
    row.gmail_failure_final_step_status;

  attemptCount =
    optionalInteger(
      row.gmail_failure_final_attempt_count,
    );

} else if (
  row.expiry_finalization_action ===
    'notify_terminal_failure'
) {
  stage =
    'token_expiry';

  errorClass =
    'token_expiry';

  errorCode =
    'token_expired_before_confirmed_delivery';

  errorMessage =
    'The client-data form token expired before confirmed Gmail delivery';

  operationStatus =
    row.expiry_final_operation_status;

  tokenStatus =
    row.expiry_final_token_status;

  stepStatus =
    row.expiry_final_step_status;

  attemptCount =
    optionalInteger(
      row.expiry_final_attempt_count,
    );

} else if (
  row.ambiguity_finalization_action ===
    'notify_terminal_failure'
) {
  stage =
    'gmail_reconciliation_ambiguity';

  errorClass =
    'gmail_reconciliation_ambiguity';

  errorCode =
    'multiple_gmail_reconciliation_matches';

  errorMessage =
    'Multiple Gmail Sent-mail matches were found for one delivery marker';

  operationStatus =
    row.ambiguity_final_operation_status;

  tokenStatus =
    row.ambiguity_final_token_status;

  stepStatus =
    row.ambiguity_final_step_status;

  attemptCount =
    optionalInteger(
      row.ambiguity_final_attempt_count,
    );

} else if (
  safeText(
    row.finalization_outcome,
    100,
  ) === 'finalized' &&
  safeText(
    row.final_operation_status,
    100,
  ) === 'failed_terminal'
) {
  stage =
    'maximum_attempts_exhausted';

  errorClass =
    'maximum_attempts_exhausted';

  errorCode =
    'maximum_attempts_exhausted';

  errorMessage =
    'Client-data request delivery reached its maximum attempts';

  operationStatus =
    row.final_operation_status;

  tokenStatus =
    row.final_token_status;

  stepStatus =
    row.final_step_status;

  attemptCount =
    optionalInteger(
      row.final_attempt_count,
    );

} else {
  throw new Error(
    'Build Terminal Delivery Failure Handoff received a non-terminal finalization result',
  );
}

if (operationStatus !== 'failed_terminal') {
  throw new Error(
    'Terminal delivery handoff requires operation status failed_terminal',
  );
}

if (stepStatus !== 'failed_terminal') {
  throw new Error(
    'Terminal delivery handoff requires collection-step status failed_terminal',
  );
}

if (
  ![
    'revoked',
    'expired',
  ].includes(tokenStatus)
) {
  throw new Error(
    'Terminal delivery handoff requires a revoked or expired token',
  );
}

const caseId =
  optionalUuid(
    context.resolved_case_id ??
    context.authoritative_case_id,
  );

const correlationId =
  optionalUuid(
    context.resolved_correlation_id ??
    context.authoritative_correlation_id,
  );

const tokenId =
  optionalUuid(
    context.resolved_token_id ??
    context.authoritative_token_id,
  );

const externalOperationId =
  optionalUuid(
    context.resolved_external_operation_id ??
    context.authoritative_operation_id,
  );

const requestCycleKey =
  safeText(
    context.resolved_request_cycle_key ??
    context.authoritative_request_cycle_key,
    200,
  );

if (
  !caseId ||
  !correlationId ||
  !tokenId ||
  !externalOperationId ||
  !requestCycleKey
) {
  throw new Error(
    'Terminal delivery handoff is missing authoritative identifiers',
  );
}

const caseState =
  safeText(
    context.authoritative_case_state ??
    context.resolved_case_state,
    100,
  ) ??
  (
    requestCycleKey === 'initial'
      ? 'created'
      : 'validation_failed'
  );

const terminalResult = {
  workflow:
    'WF02',

  result:
    'failed_terminal',

  case_id:
    caseId,

  correlation_id:
    correlationId,

  request_cycle_key:
    requestCycleKey,

  token_id:
    tokenId,

  external_operation_id:
    externalOperationId,

  operation_status:
    'failed_terminal',

  case_state:
    caseState,
};

return {
  json: {
    source_variant:
      'explicit_internal',

    source_workflow_name:
      'WF02 — Request Client Data',

    source_workflow_id:
      safeText(
        $workflow.id,
        200,
      ),

    source_execution_id:
      safeText(
        $execution.id,
        200,
      ),

    case_id:
      caseId,

    correlation_id:
      correlationId,

    step_id:
      optionalUuid(
        context.collect_step_id ??
        context.resolved_collect_step_id ??
        context.resolved_step_id,
      ),

    submission_id:
      null,

    external_operation_id:
      externalOperationId,

    error_class:
      errorClass,

    error_code:
      errorCode,

    error_message:
      errorMessage,

    retryable:
      false,

    severity:
      'error',

    requires_intervention:
      true,

    error_details: {
      stage,

      request_cycle_key:
        requestCycleKey,

      token_id:
        tokenId,

      operation_status:
        operationStatus,

      step_status:
        stepStatus,

      token_status:
        tokenStatus,

      final_attempt_count:
        attemptCount,

      wf02_terminal_result:
        terminalResult,
    },
  },
};

// WF02 returns the sanitized failed_terminal result only after
// the WF99 terminal-intervention handoff completed.

const input = $json ?? {};

const result =
  input.error_details &&
  typeof input.error_details === 'object' &&
  !Array.isArray(input.error_details)
    ? input.error_details.wf02_terminal_result
    : null;

if (
  !result ||
  typeof result !== 'object' ||
  Array.isArray(result) ||
  result.result !== 'failed_terminal'
) {
  throw new Error(
    'WF02 terminal result was not preserved through the WF99 handoff',
  );
}

return {
  json: result,
};

const input = $json ?? {};

if (input.workflow !== 'WF02') {
  throw new Error(
    'WF02 return boundary requires workflow equal to WF02',
  );
}

if (
  typeof input.result !== 'string' ||
  input.result.trim() === ''
) {
  throw new Error(
    'WF02 return boundary requires a non-empty result',
  );
}

return {
  json: {
    ...input,
    result: input.result.trim(),
  },
};
